\setcounter{problem}{14}
\begin{problem}[Cutwidth]
Find a vertex order $\pi$ minimizing
\[\max_{1\leq i<n}|\{uv\in E:\pi(u)\leq i<\pi(v)\text{ or }\pi(v)\leq i<\pi(u)\}|.\]
The objective is the largest number of edges crossing a prefix cut. It represents the largest simultaneous communication or wiring requirement along a linear layout.
The comparison uses quantum QRAM time and classical RAM time on an explicit graph.
\end{problem}
\speedupheading
\complexity{Quantum}{$O^*(1.817^n)$, quantum vertex-ordering dynamic programming.}
A prefix subset determines the number of crossing edges. The recurrence minimizes the maximum of this local cut size and the value of the preceding prefix. Its quantum implementation uses partial subset preprocessing and recursive minimum finding, with exponential coherent memory.
\complexity{Classical}{$O^*(2^n)$ time and space, subset dynamic programming; $O^*(4^n)$ time with polynomial space, divide and conquer.}
The subset algorithm processes prefixes in order of their cardinality and retains the best maximum-cut value for each prefix. These bounds concern arbitrary cutwidth as a function of vertex count. Algorithms parameterized by a small target cutwidth can instead be used on instances in that regime.
\dimensionlabel{Strength}{strengthPolynomial} Polynomial speedup from $2^n$ to $1.817^n$ in the exponential-memory comparison, based on amplitude amplification.
\dimensionlabel{Evidence}{evidencePartial} Rigorous template and problem upper bounds, with partial evidence against the displayed general classical bound.
\dimensionlabel{Hardware}{hardwareExponential} Polynomial active registers represent a subset and its cut size. Exponentially many stored dynamic-programming values must be coherently accessible, and useful searches require fault tolerance.
\subhead{Algorithm}
\begin{algorithmindex}{15}
\item \href{https://arxiv.org/pdf/1807.05209}{Ambainis et al., \emph{Quantum Speedups for Exponential-Time Dynamic Programming Algorithms} (SODA 2019)}. Corollary 5 and equation (3): quantum ordering recurrence and cutwidth application.
\item \href{https://doi.org/10.1007/s00224-011-9312-0}{Bodlaender et al., \emph{A Note on Exact Algorithms for Vertex Ordering Problems on Graphs} (2012)}. The dynamic-programming and polynomial-space divide-and-conquer constructions for vertex-ordering objectives.
\end{algorithmindex}
